import React, { useEffect, useState } from "react";

function Dashboard() {
  const [resumes, setResumes] = useState([]);

  // 🔄 Fetch resumes
  useEffect(() => {
    fetchResumes();
  }, []);

  const fetchResumes = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/my", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await res.json();
      setResumes(data);
    } catch (err) {
      console.error(err);
    }
  };

  // ❌ Delete resume
  const handleDelete = async (id) => {
    try {
      const token = localStorage.getItem("token");

      await fetch(`http://localhost:5000/api/resume/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      // refresh list
      fetchResumes();
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Your Saved Resumes</h2>

      <div style={styles.topButtons}>
        <button
          style={styles.primaryBtn}
          onClick={() => (window.location.href = "/")}
        >
          Analyze Resume
        </button>

        <button
          style={styles.logoutBtn}
          onClick={() => {
            localStorage.removeItem("token");
            window.location.href = "/login";
          }}
        >
          Logout
        </button>
      </div>

      {resumes.length === 0 ? (
        <p>No resumes found</p>
      ) : (
        <div style={styles.grid}>
          {resumes.map((item) => (
            <div key={item._id} style={styles.card}>
              <div style={styles.cardHeader}>
                <h3>ATS Score: {item.atsScore}</h3>
              </div>

              <div style={styles.resumeBox}>
                {item.resume}
              </div>

              <button
                style={styles.deleteBtn}
                onClick={() => handleDelete(item._id)}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// 🎨 Styles
const styles = {
  container: {
    padding: "30px",
    color: "white",
  },

  heading: {
    marginBottom: "20px",
  },

  topButtons: {
    display: "flex",
    justifyContent: "flex-end",
    gap: "10px",
    marginBottom: "20px",
  },

  primaryBtn: {
    background: "#007bff",
    color: "white",
    border: "none",
    padding: "10px 15px",
    borderRadius: "6px",
    cursor: "pointer",
  },

  logoutBtn: {
    background: "red",
    color: "white",
    border: "none",
    padding: "10px 15px",
    borderRadius: "6px",
    cursor: "pointer",
  },

  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(350px, 1fr))",
    gap: "20px",
  },

  card: {
    background: "#111",
    padding: "20px",
    borderRadius: "10px",
    boxShadow: "0 0 10px rgba(0,0,0,0.5)",
    display: "flex",
    flexDirection: "column",
  },

  cardHeader: {
    marginBottom: "10px",
  },

  resumeBox: {
    background: "#000",
    padding: "10px",
    borderRadius: "6px",
    height: "200px",
    overflowY: "auto",
    fontSize: "12px",
    whiteSpace: "pre-wrap",
    marginBottom: "10px",
  },

  deleteBtn: {
    marginTop: "auto",
    background: "orange",
    border: "none",
    padding: "10px",
    borderRadius: "6px",
    cursor: "pointer",
  },
};

export default Dashboard;
